package in.finseq.insurance;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class Customer360Activity extends FinseqActivity{
 int customerId;LinearLayout root,body,content;JSONObject snapshot,customer;
 @Override public void onCreate(Bundle state){super.onCreate(state);customerId=getIntent().getIntExtra("customer_id",0);if(customerId<=0){finish();return;}renderShell();load();}
 void renderShell(){root=Ui.column(this);Ui.appHeader(root,this,"Customer 360°");body=Ui.contentColumn(this);root.addView(body);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);body.addView(content);setContentView(Ui.scroll(this,root));}
 void load(){Ui.run(this,new Runnable(){public void run(){try{final JSONObject data=ApiClient.get(Customer360Activity.this,"/api/v1/sync");Ui.ui(Customer360Activity.this,new Runnable(){public void run(){snapshot=data;JSONArray all=data.optJSONArray("customers");customer=null;for(int i=0;all!=null&&i<all.length();i++){JSONObject item=all.optJSONObject(i);if(item!=null&&item.optInt("id")==customerId){customer=item;break;}}showOverview();}});}catch(final Exception error){Ui.ui(Customer360Activity.this,new Runnable(){public void run(){Ui.toast(Customer360Activity.this,error.getMessage());}});}}});}
 void showOverview(){content.removeAllViews();if(customer==null){content.addView(Ui.sub(this,"Client not found or access denied."));return;}LinearLayout hero=Ui.card(this);LinearLayout line=new LinearLayout(this);line.setOrientation(LinearLayout.HORIZONTAL);line.setGravity(Gravity.CENTER_VERTICAL);line.addView(Ui.avatar(this,customer.optString("name")),new LinearLayout.LayoutParams(Ui.dp(this,58),Ui.dp(this,58)));LinearLayout tt=new LinearLayout(this);tt.setOrientation(LinearLayout.VERTICAL);tt.setPadding(Ui.dp(this,12),0,0,0);tt.addView(Ui.text(this,customer.optString("name"),21,true));tt.addView(Ui.sub(this,customer.optString("code")+" · "+customer.optString("mobile")));line.addView(tt,new LinearLayout.LayoutParams(0,-2,1));hero.addView(line);hero.addView(Ui.sub(this,"Family Head: "+customer.optString("family_head")+" · Members: "+customer.optInt("family_members",1)));hero.addView(Ui.text(this,"Net Due: "+Ui.money(customer.optDouble("family_due"))+"    Advance: "+Ui.money(customer.optDouble("family_advance")),15,true));content.addView(hero);
  LinearLayout tabs=new LinearLayout(this);tabs.setOrientation(LinearLayout.HORIZONTAL);String[] labels={"Overview","Insurance","Mutual Funds","Accounts"};for(final String label:labels){Button button=Ui.outlineButton(this,label);tabs.addView(button,new LinearLayout.LayoutParams(0,-2,1));button.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(label.equals("Overview"))overviewBody();else if(label.equals("Insurance"))insuranceBody();else if(label.equals("Mutual Funds"))mfBody();else accountBody();}});}content.addView(tabs);overviewBody();}
 void clearAfterTabs(){while(content.getChildCount()>2)content.removeViewAt(2);}
 void overviewBody(){clearAfterTabs();LinearLayout c=Ui.card(this);c.addView(Ui.text(this,"Client Profile",18,true));for(String[] field:new String[][]{{"Code","code"},{"Mobile","mobile"},{"Email","email"},{"Address","address"},{"PAN","pan"},{"Referred By","referred_by"}})c.addView(Ui.sub(this,field[0]+": "+customer.optString(field[1],"—")));Button family=Ui.button(this,"Family & Balance Tools");family.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(Customer360Activity.this,FamilyToolsActivity.class).putExtra("focus_customer_id",customerId));}});c.addView(family);content.addView(c);familyMembers();}
 void familyMembers(){JSONArray all=snapshot.optJSONArray("customers");int rootId=customer.optInt("family_root_id",customerId),count=0;LinearLayout group=Ui.card(this);group.addView(Ui.text(this,"Family Members",18,true));for(int i=0;all!=null&&i<all.length();i++){JSONObject member=all.optJSONObject(i);if(member==null||member.optInt("family_root_id",member.optInt("id"))!=rootId)continue;count++;final int id=member.optInt("id");LinearLayout row=Ui.actionRow(this,"♙",member.optString("name"),member.optString("code")+" · "+member.optString("mobile")+" · "+(id==rootId?"Family Head":"Member"));row.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(id!=customerId)startActivity(new Intent(Customer360Activity.this,Customer360Activity.class).putExtra("customer_id",id));}});group.addView(row);}if(count==0)group.addView(Ui.sub(this,"No family members linked."));content.addView(group);}
 void insuranceBody(){clearAfterTabs();JSONArray policies=snapshot.optJSONArray("policies");int count=0;for(int i=0;policies!=null&&i<policies.length();i++){JSONObject p=policies.optJSONObject(i);if(p==null||p.optInt("customer_id")!=customerId)continue;count++;LinearLayout card=Ui.card(this);card.addView(Ui.text(this,p.optString("policy_number"),16,true));card.addView(Ui.sub(this,p.optString("insurer")+" · "+p.optString("type")+" · "+p.optString("subtype")));card.addView(Ui.sub(this,"Vehicle: "+p.optString("vehicle","—")+" · Expiry: "+p.optString("expiry_date")));card.addView(Ui.text(this,"Premium: "+Ui.money(p.optDouble("premium")),15,true));final int id=p.optInt("id");card.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(Customer360Activity.this,PolicyDetailActivity.class).putExtra("policy_id",id));}});content.addView(card);}if(count==0)content.addView(Ui.sub(this,"No insurance policies are linked to this client."));}
 void mfBody(){clearAfterTabs();LinearLayout loading=Ui.card(this);loading.addView(Ui.sub(this,"Loading linked NSE profile, SIPs and mandates…"));content.addView(loading);Ui.run(this,new Runnable(){public void run(){try{final JSONObject result=ApiClient.get(Customer360Activity.this,"/api/v2/mf/customer/"+customerId+"/overview");Ui.ui(Customer360Activity.this,new Runnable(){public void run(){renderMf(result);}});}catch(final Exception error){Ui.ui(Customer360Activity.this,new Runnable(){public void run(){clearAfterTabs();content.addView(Ui.sub(Customer360Activity.this,"MF details unavailable: "+error.getMessage()));}});}}});}
 void renderMf(JSONObject data){clearAfterTabs();JSONArray investors=data.optJSONArray("investors"),profiles=data.optJSONArray("profiles"),sips=data.optJSONArray("sip_activity"),mandates=data.optJSONArray("mandates");JSONObject client=data.optJSONObject("customer");final String pan=client==null?"":client.optString("pan");
  LinearLayout headline=Ui.card(this);headline.addView(Ui.text(this,"Mutual Fund · NSE Invest",20,true));headline.addView(Ui.sub(this,"Linked by customer ID, PAN or registered UCC"));headline.addView(Ui.text(this,(profiles==null?0:profiles.length())+" Profiles   ·   "+(sips==null?0:sips.length())+" SIP events   ·   "+(mandates==null?0:mandates.length())+" Mandates",15,true));content.addView(headline);
  LinearLayout actions=Ui.card(this);actions.addView(Ui.text(this,"Client checks",17,true));Button kyc=Ui.greenButton(this,"Check KYC Status");kyc.setEnabled(!pan.isEmpty());kyc.setOnClickListener(new View.OnClickListener(){public void onClick(View v){checkKyc(pan);}});actions.addView(kyc);Button sync=Ui.button(this,"Sync this client's SIPs");sync.setEnabled(data.optJSONArray("uccs")!=null&&data.optJSONArray("uccs").length()>0);sync.setOnClickListener(new View.OnClickListener(){public void onClick(View v){syncSips();}});actions.addView(sync);Button orders=Ui.greenButton(this,"My Orders · Select Dates");orders.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(Customer360Activity.this,OrdersActivity.class).putExtra("customer_id",customerId));}});actions.addView(orders);content.addView(actions);
  section("NSE Profiles",profiles,"No linked NSE profile. Sync Client Master first.","profile");section("SIP / XSIP Activity",sips,"No SIP activity synced for this client.","sip");section("Mandate Details",mandates,"No mandate details synced for this client.","mandate");
  if((investors==null||investors.length()==0)&&(profiles==null||profiles.length()==0)){LinearLayout card=Ui.card(this);card.addView(Ui.sub(this,"This customer has no exact MF link. Check PAN or link the investor from MF workspace."));Button open=Ui.button(this,"Open MF Workspace");open.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(Customer360Activity.this,InvestActivity.class));}});card.addView(open);content.addView(card);}
 }
 void section(String title,JSONArray rows,String empty,String kind){LinearLayout header=Ui.card(this);header.addView(Ui.text(this,title,18,true));header.addView(Ui.sub(this,(rows==null?0:rows.length())+" record(s)"));content.addView(header);if(rows==null||rows.length()==0){content.addView(Ui.sub(this,empty));return;}for(int i=0;i<Math.min(rows.length(),30);i++){final JSONObject item=rows.optJSONObject(i);if(item==null)continue;LinearLayout card=Ui.card(this);if(kind.equals("profile")){card.addView(Ui.text(this,item.optString("name","NSE Client"),16,true));card.addView(Ui.sub(this,"UCC "+item.optString("ucc")+" · PAN "+item.optString("pan")));card.addView(Ui.badge(this,item.optString("status","Unknown"),Ui.GREEN));}else if(kind.equals("mandate")){JSONObject fields=item.optJSONObject("fields");card.addView(Ui.text(this,fields==null?"Mandate":fields.optString("mandate_id",fields.optString("member_mandate_id","Mandate")),16,true));card.addView(Ui.sub(this,"UCC "+item.optString("ucc")+" · "+item.optString("fetched_at")));if(fields!=null)card.addView(Ui.sub(this,"Status: "+fields.optString("mandate_status",fields.optString("status","—"))));}else{card.addView(Ui.text(this,item.optString("scheme_name","SIP"),16,true));card.addView(Ui.sub(this,item.optString("category")+" · "+item.optString("status")+" · "+item.optString("activity_date")));card.addView(Ui.sub(this,"UCC "+item.optString("client_code")+" · SIP "+item.optString("sip_reg_no")));}card.setOnClickListener(new View.OnClickListener(){public void onClick(View v){JSONObject fields=item.optJSONObject("fields");new AlertDialog.Builder(Customer360Activity.this).setTitle(title).setMessage(formatFields(fields==null?item:fields)).setPositiveButton("Close",null).show();}});content.addView(card);}}
 String formatFields(JSONObject data){StringBuilder text=new StringBuilder();Iterator<String> keys=data.keys();while(keys.hasNext()){String key=keys.next();if(key.equals("fields"))continue;Object value=data.opt(key);text.append(key.replace('_',' ')).append(": ").append(value==null||value==JSONObject.NULL?"—":String.valueOf(value)).append("\n\n");}return text.toString();}
 void checkKyc(final String pan){Ui.run(this,new Runnable(){public void run(){try{final JSONObject result=ApiClient.post(Customer360Activity.this,"/api/v2/mf/kyc-check",new JSONObject().put("pan",pan));Ui.ui(Customer360Activity.this,new Runnable(){public void run(){new AlertDialog.Builder(Customer360Activity.this).setTitle("NSE KYC · "+result.optString("status")).setMessage("Decision: "+result.optString("decision")+"\nName: "+result.optString("name")+"\nRemarks: "+result.optString("remark")+"\nChecked: "+result.optString("status_date")).setPositiveButton("Close",null).show();}});}catch(final Exception error){Ui.ui(Customer360Activity.this,new Runnable(){public void run(){Ui.toast(Customer360Activity.this,error.getMessage());}});}}});}
 void syncSips(){Ui.run(this,new Runnable(){public void run(){try{final JSONObject result=ApiClient.post(Customer360Activity.this,"/api/v2/mf/customer/"+customerId+"/sip/sync",new JSONObject());Ui.ui(Customer360Activity.this,new Runnable(){public void run(){JSONObject counts=result.optJSONObject("result");Ui.toast(Customer360Activity.this,counts==null?"SIP sync complete":counts.optInt("synced")+" UCC synced · "+counts.optInt("sip_records")+" SIPs · "+(counts.optJSONArray("errors")==null?0:counts.optJSONArray("errors").length())+" failed");mfBody();}});}catch(final Exception error){Ui.ui(Customer360Activity.this,new Runnable(){public void run(){Ui.toast(Customer360Activity.this,error.getMessage());}});}}});}
 void accountBody(){clearAfterTabs();LinearLayout c=Ui.card(this);c.addView(Ui.text(this,"Family Financial Position",18,true));c.addView(Ui.text(this,"Due: "+Ui.money(customer.optDouble("family_due")),16,true));c.addView(Ui.text(this,"Advance: "+Ui.money(customer.optDouble("family_advance")),16,true));Button accounts=Ui.greenButton(this,"Open Account Register");accounts.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(Customer360Activity.this,AccountsActivity.class));}});c.addView(accounts);Button family=Ui.button(this,"Family & Balance Tools");family.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(Customer360Activity.this,FamilyToolsActivity.class).putExtra("focus_customer_id",customerId));}});c.addView(family);content.addView(c);familyMembers();}
}
